// src/pages/Battle.jsx
import React, { useEffect, useMemo, useState } from "react";
import "./battle.css";
import { cards } from "../data/cards";

/* ========= 小ユーティリティ ========= */
function getParamPlayerIndex() {
  const p = new URLSearchParams(window.location.search).get("p");
  return p === "1" ? 1 : 0; // デフォルト0
}
function deepClone(obj) { return JSON.parse(JSON.stringify(obj)); }

// 盤面シンボル合計（軽減計算用）
function getAvailableReductionsFromBoard(zones) {
  const sum = { red:0, blue:0, green:0, white:0, yellow:0, purple:0 };
  for (const z of zones) {
    if (!z || !z.card) continue;
    const { symbolColor, symbolCount = 1 } = z.card;
    sum[symbolColor] = (sum[symbolColor] || 0) + symbolCount;
  }
  return sum;
}
// 実支払コスト
function calcActualCost(card, availableReductions) {
  let reduce = 0;
  for (const color of Object.keys(card.reduction)) {
    const need = card.reduction[color] || 0;
    const have = availableReductions[color] || 0;
    reduce += Math.min(need, have);
  }
  return Math.max(0, card.cost - reduce);
}
// 現在コア数→レベル情報
function levelFromCores(card, cores) {
  let current = card.levels[0];
  for (const lvInfo of card.levels) {
    if (cores >= lvInfo.core) current = lvInfo;
  }
  return current;
}

/* ========= WebSocket ========= */
function useWS(onMessage) {
  const [ws, setWs] = useState(null);
  useEffect(() => {
    const sock = new WebSocket("ws://localhost:8080");
    sock.addEventListener("open", () => {
      sock.send(JSON.stringify({ type: "join", roomId: "room1" }));
    });
    sock.addEventListener("message", (ev) => {
      try { onMessage?.(JSON.parse(ev.data)); } catch {}
    });
    setWs(sock);
    return () => sock.close();
  }, [onMessage]);
  return ws;
}

export default function Battle() {
  /* ==== ローカルのデッキ/手札（非同期共有しない） ==== */
  const fullDeck = useMemo(() => {
    const deck = [];
    for (let i = 0; i < 20; i++) {
      const c = cards[i % cards.length];
      deck.push({ ...c, deckIndex: i });
    }
    return deck;
  }, []);
  const [deck, setDeck] = useState([]);
  const [handCards, setHandCards] = useState([]);
  const [selectedHandIndex, setSelectedHandIndex] = useState(null);

  /* ==== サーバ公開ステート ==== */
  const myIdx = useMemo(() => getParamPlayerIndex(), []);
  const [serverState, setServerState] = useState(null);
  // onMessage を useCallbackにして依存を固定してもOK
  const ws = useWS((msg) => {
    if (msg.type === "state" || msg.type === "attack_declared" || msg.type === "resolved") {
      setServerState(msg.state);
    }
  });

  const isMyTurn = serverState ? serverState.turn === myIdx : false;
  const phase = serverState?.phase || "START";
  const myPub = serverState?.players?.[myIdx];
  const oppPub = serverState?.players?.[(myIdx === 0) ? 1 : 0];

  // 初期ドロー（4）＆ローカル山札
  useEffect(() => {
    const d = [...fullDeck];
    const drawn = [];
    for (let i = 0; i < 4; i++) {
      const idx = Math.floor(Math.random() * d.length);
      drawn.push(d.splice(idx, 1)[0]);
    }
    setHandCards(drawn);
    setDeck(d);
  }, [fullDeck]);

  // サーバへ state 同期（簡易：信頼モデル）
  const syncServer = (next) => {
    ws?.readyState === 1 && ws.send(JSON.stringify({ type: "sync_state", state: next }));
  };

  /* ==== 召喚・Lv操作（ローカル→サーバ公開ステートに反映） ==== */
  const summonToZone = (zoneIdx) => {
    if (!serverState || !isMyTurn) return;
    if (selectedHandIndex === null) return;
    if (myPub.zones[zoneIdx] !== null) return;

    const card = handCards[selectedHandIndex];
    const reductions = getAvailableReductionsFromBoard(myPub.zones);
    const actualCost = calcActualCost(card, reductions);
    const lv1 = card.levels[0];
    const needCores = lv1.core;
    const totalPay = actualCost + needCores;

    if (myPub.reserve < totalPay) {
      alert(`コア不足：必要${totalPay}（コスト${actualCost} + Lv${lv1.lv}に必要${needCores}） / 手持ち${myPub.reserve}`);
      return;
    }

    // 公開ステート更新
    const next = deepClone(serverState);
    next.players[myIdx].reserve -= totalPay;
    next.players[myIdx].trash += actualCost; // コスト分はTRASHへ
    next.players[myIdx].zones[zoneIdx] = { card, cores: needCores, attacked: false };

    setServerState(next);
    syncServer(next);

    // 手札から除去
    const newHand = [...handCards];
    newHand.splice(selectedHandIndex, 1);
    setHandCards(newHand);
    setSelectedHandIndex(null);
  };

  const levelUp = (zoneIdx) => {
    if (!serverState || !isMyTurn) return;
    const z = myPub.zones[zoneIdx];
    if (!z) return;
    const curr = levelFromCores(z.card, z.cores);
    const levels = z.card.levels;
    const i = levels.findIndex(l => l.lv === curr.lv);
    const nextLv = levels[i + 1];
    if (!nextLv) return;
    const needMore = nextLv.core - z.cores;
    if (needMore <= 0) return;
    if (myPub.reserve < needMore) {
      alert(`コア不足：Lv${curr.lv}→Lv${nextLv.lv} +${needMore} / 手持ち${myPub.reserve}`);
      return;
    }
    const next = deepClone(serverState);
    next.players[myIdx].reserve -= needMore;
    next.players[myIdx].zones[zoneIdx].cores = nextLv.core;
    setServerState(next);
    syncServer(next);
  };

  const levelDown = (zoneIdx) => {
    if (!serverState || !isMyTurn) return;
    const z = myPub.zones[zoneIdx];
    if (!z) return;
    const curr = levelFromCores(z.card, z.cores);
    const levels = z.card.levels;
    const i = levels.findIndex(l => l.lv === curr.lv);
    const prevLv = levels[i - 1];
    if (!prevLv) return;
    const refund = z.cores - prevLv.core;
    const next = deepClone(serverState);
    next.players[myIdx].reserve += refund;
    next.players[myIdx].zones[zoneIdx].cores = prevLv.core;
    setServerState(next);
    syncServer(next);
  };

  /* ==== アタック / ブロック / ターン終了 ==== */
  const attackWith = (zoneIdx) => {
    if (!serverState || !isMyTurn) return;
    if (!(phase === "ATTACK" || phase === "MAIN")) return; // 簡易
    const z = myPub.zones[zoneIdx];
    if (!z || z.attacked) return;
    ws?.send(JSON.stringify({ type: "attack", zoneIdx }));
  };
  const sendBlock = (blockerZoneIdx /* or null */) => {
    ws?.send(JSON.stringify({ type: "block", blockerZoneIdx }));
  };
  const endTurn = () => {
    if (!serverState || !isMyTurn) return;
    ws?.send(JSON.stringify({ type: "end_turn" }));
  };

  // ブロックモーダルの表示条件
  const shouldShowBlock =
    serverState?.phase === "BLOCK" &&
    serverState?.lastAttack &&
    serverState.lastAttack.attackerIdx !== myIdx;

  return (
    <div className="board">
      {/* === 自分側（左） === */}
      <section className="side my-side">
        <header className="hud hud-top">
          <span className="hud-item">LIFE <b>{myPub?.life ?? 0}</b></span>
          <span className="hud-item">RESERVE <b>{myPub?.reserve ?? 0}</b></span>
          <span className="hud-item">TRASH <b>{myPub?.trash ?? 0}</b></span>
          <span className="spacer" />
          <button className="btn next-btn" onClick={endTurn} disabled={!isMyTurn}>ターン終了</button>
        </header>

        {/* 自分のフィールド */}
        <div className="field">
          {(myPub?.zones ?? [null,null,null,null]).map((z, i) => {
            if (!z) {
              return (
                <div
                  key={i}
                  className={`zone ${selectedHandIndex !== null && isMyTurn ? "placeable" : ""}`}
                  onClick={() => (isMyTurn ? summonToZone(i) : null)}
                >
                  <span>ゾーン{i + 1}</span>
                </div>
              );
            }
            const info = levelFromCores(z.card, z.cores);
            return (
              <div key={i} className="zone filled">
                <img src={z.card.img} alt={z.card.name} className="zone-card" />
                <div className="zone-badge">Lv{info.lv} / BP {info.bp}</div>
                <div className="zone-controls">
                  <button className="btn-small" onClick={() => isMyTurn && levelDown(i)}>-</button>
                  <button className="btn-small" onClick={() => isMyTurn && levelUp(i)}>+</button>
                  <button
                    className={`btn-small warn ${z.attacked ? "disabled" : ""}`}
                    onClick={() => isMyTurn && attackWith(i)}
                    disabled={!!z.attacked || !isMyTurn}
                    title={z.attacked ? "このターンは攻撃済み" : "アタックする"}
                  >
                    ATK
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {/* 手札 */}
        <footer className="hand hand-bottom">
          {handCards.length === 0 ? (
            <span>手札ゾーン</span>
          ) : (
            <div className="hand-cards">
              {handCards.map((card, idx) => (
                <img
                  key={card.deckIndex}
                  src={card.img}
                  alt={card.name}
                  className={`card-img ${selectedHandIndex === idx ? "selected" : ""}`}
                  onClick={() => setSelectedHandIndex(prev => (prev === idx ? null : idx))}
                  draggable={false}
                  title={card.name}
                />
              ))}
            </div>
          )}
        </footer>
      </section>

      {/* 仕切り線 */}
      <div className="divider" />

      {/* === 相手側（右） === */}
      <section className="side op-side">
        <header className="hand hand-top">
          <span>V手札ゾーン</span>
        </header>

        <div className="field">
          {(oppPub?.zones ?? [null,null,null,null]).map((z, i) => (
            <div key={i} className={`zone ${z ? "filled" : ""}`}>
              {z ? (
                <>
                  <img src={z.card.img} alt={z.card.name} className="zone-card" />
                  <div className="zone-badge">Lv{levelFromCores(z.card, z.cores).lv}</div>
                </>
              ) : (
                <span>{i + 1}ゾーン</span>
              )}
            </div>
          ))}
        </div>

        <footer className="hud hud-bottom">
          <span className="hud-item red">LIFE <b>{oppPub?.life ?? 0}</b></span>
          <span className="hud-item red">RESERVE <b>{oppPub?.reserve ?? 0}</b></span>
          <span className="hud-item red">TRASH <b>{oppPub?.trash ?? 0}</b></span>
        </footer>
      </section>

      {/* === ブロックモーダル === */}
      {shouldShowBlock && (
        <div className="block-modal">
          <div className="block-card">
            <h3 style={{margin:"0 0 8px"}}>ブロック選択</h3>
            <p style={{margin:"0 0 10px"}}>ブロックするスピリットを選ぶか、ノーブロックを押してください。</p>
            <div className="block-grid">
              {(myPub?.zones ?? []).map((z, i) => (
                <button
                  key={i}
                  className="block-btn"
                  onClick={() => sendBlock(z ? i : null)}
                  disabled={!z}
                >
                  {z ? `ゾーン${i+1}でブロック` : "（なし）"}
                </button>
              ))}
            </div>
            <div style={{marginTop:12, display:"flex", gap:8, justifyContent:"flex-end"}}>
              <button className="block-btn outline" onClick={() => sendBlock(null)}>ノーブロック</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
